shellCommands.command:
node -e "
import('./server.js').then(async ({ startServer }) => {
  const srv = await startServer(3099);
  const res = await fetch('http://localhost:3099/');
  console.log('home status:', res.status);
  const html = await res.text();
  console.log('has Currently reading:', html.includes('Currently reading'));
  console.log('has Add a book link:', html.includes('/books/new'));

  // create a book
  const created = await fetch('http://localhost:3099/books', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: 'title=Hyperion&author=Dan+Simmons&notes=great',
    redirect: 'manual',
  });
  console.log('create status:', created.status, '->', created.headers.get('location'));
  const id = created.headers.get('location').split('/').pop();

  // detail page
  const detail = await fetch('http://localhost:3099/books/' + id);
  const dhtml = await detail.text();
  console.log('detail status:', detail.status);
  console.log('detail has title:', dhtml.includes('Hyperion'));
  console.log('detail has author:', dhtml.includes('Dan Simmons'));
  console.log('detail has notes:', dhtml.includes('great'));
  console.log('detail has share link:', dhtml.includes('http://localhost:3099/books/' + id));

  // mark finished
  const fin = await fetch('http://localhost:3099/books/' + id + '/finished', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: 'finished=true',
    redirect: 'manual',
  });
  console.log('finish status:', fin.status);

  // home now shows it under Finished
  const home2 = await fetch('http://localhost:3099/');
  const h2 = await home2.text();
  console.log('home has Hyperion:', h2.includes('Hyperion'));

  srv.close();
  // cleanup data file
  const fs = await import('node:fs/promises');
  await fs.unlink('books.json').catch(() => {});
  process.exit(0);
});
"
